#include <stdio.h>
/*
 * ex03：中断嵌套的响应顺序（可抢占的优先级调度）
 * 为什么：多级中断里，高优先级中断可以打断低优先级的服务程序，这就是「中断嵌套」。
 * 模型：IRQ 控制器维护一个「已到达但没处理完」的池子，每个时刻让池子里
 *      优先级最高（数值最小）的那个占用 CPU；被打断的那个不丢，等空闲后
 *      按优先级重新排上。这样既能看到抢占，又保证没有中断被饿死。
 */
typedef struct {
    const char *name;
    int arrive;    /* 到达时刻 */
    int duration;  /* 需要服务几个时间单位 */
    int prio;      /* 越小优先级越高 */
} Irq;

int main(void) {
    Irq irqs[] = {
        {"时钟",  0, 4, 3},
        {"网卡",  2, 6, 1},   /* 最高优先级：会打断时钟 */
        {"磁盘",  3, 3, 2},   /* 中优先级：低于网卡，只能等 */
        {"键盘", 10, 2, 4}    /* 最低优先级：排在最后 */
    };
    int n = (int)(sizeof(irqs) / sizeof(irqs[0]));
    int arrived[4] = {0}, remain[4], done = 0, current = -1, now = 0;
    int start[4], fin[4];

    for (int i = 0; i < n; i++) { remain[i] = irqs[i].duration; start[i] = -1; fin[i] = -1; }

    printf("时刻  事件\n");
    printf("------------------------------------------------------------\n");
    while (done < n && now < 100) {
        /* 1) 本时刻新到达的中断全部入池 */
        for (int i = 0; i < n; i++) {
            if (!arrived[i] && irqs[i].arrive == now) {
                arrived[i] = 1;
                printf("%4d  %s 到达（优先级 %d）\n", now, irqs[i].name, irqs[i].prio);
            }
        }
        /* 2) 从池子里挑优先级最高的占用 CPU */
        int best = -1;
        for (int i = 0; i < n; i++)
            if (arrived[i] && remain[i] > 0)
                if (best < 0 || irqs[i].prio < irqs[best].prio) best = i;

        if (best != current && best >= 0) {
            if (start[best] < 0) start[best] = now;   /* 第一次被服务 = 响应时刻 */
            if (current >= 0)
                printf("%4d  %s 抢占 %s（%s 剩余 %d 个单位，等回来继续）\n",
                       now, irqs[best].name, irqs[current].name,
                       irqs[current].name, remain[current]);
            current = best;
        }
        /* 3) 推进一个时间单位 */
        if (current >= 0) {
            remain[current]--;
            if (remain[current] == 0) {
                printf("%4d  %s 服务结束\n", now + 1, irqs[current].name);
                fin[current] = now + 1;
                done++;
                current = -1;
            }
        }
        now++;
    }
    printf("------------------------------------------------------------\n");
    printf("全部中断处理完成，总耗时=%d 个时间单位\n\n", now);
    printf("%-6s %-8s %-10s %-10s %-8s\n", "中断", "到达", "开始服务", "响应延迟", "服务完成");
    int worst = 0;
    for (int i = 0; i < n; i++) {
        int lat = start[i] - irqs[i].arrive;
        printf("%-6s %-8d %-10d %-10d %-8d\n", irqs[i].name, irqs[i].arrive, start[i], lat, fin[i]);
        if (lat > worst) worst = lat;
    }
    printf("\n最坏响应延迟 = %d 个时间单位（磁盘：等网卡跑完）\n", worst);
    printf("\n关键结论：\n");
    printf("  1) 网卡(优先级1)打断了时钟，时钟没被丢弃，而是等更高优先级都跑完再继续 -> 这就是嵌套；\n");
    printf("  2) 磁盘(优先级2)到达时网卡正在跑，只能排队 -> 响应延迟 = 网卡剩余服务时间；\n");
    printf("  3) 若每个服务程序都很长，低优先级中断会被反复推迟 -> 这就是「中断风暴」。\n");
    return 0;
}
